% 2.4 GHz INSET-FED MICROSTRIP PATCH ANTENNA - PROTOTYPE SIMULATION
% Requires Antenna Toolbox, MATLAB R2021a or later.
%
% Changes from previous version:
%  - Two-stage sweep: wide coarse sweep finds the true resonance, then a
%    fine sweep covers the full 2.400-2.4835 GHz band plus the resonance.
%  - Warns if the S11 minimum sits on a sweep edge (not a real dip).
%  - Pass/fail is judged across the whole band, not at a single frequency.
%  - Fixed, explicit mesh so results are repeatable; optional mesh study.
%  - Loss tangent set to a realistic FR-4 value (edit for your laminate).
%  - Pattern computed once, explicitly as gain; realized gain and
%    front-to-back ratio reported.
%  - Suggested next patch length printed if the resonance is off-centre.
%  - Optional epsR tolerance study.

clear; clc; close all;

%% 1. SETTINGS
bandLow  = 2.400e9;                  % Wi-Fi / BLE band
bandHigh = 2.4835e9;
fCenter  = (bandLow + bandHigh)/2;   % 2.44175 GHz design centre
Z0       = 50;                       % reference impedance (ohm)
s11Limit = -10;                      % match criterion (dB)

coarseSpan = [2.0e9 3.0e9];          % wide search for true resonance
coarseStep = 20e6;
fineMargin = 80e6;                   % extra span beyond band / resonance
fineStep   = 2e6;

maxEdge = 2.0e-3;                    % mesh max edge length (m)

runMeshStudy      = false;           % slow - run once to validate maxEdge
meshStudyEdges    = [4 3 2 1.5]*1e-3;
runToleranceStudy = false;           % slow - epsR +/- tolerance
epsRTolerance     = 0.2;

%% 2. BOARD, SUBSTRATE, GEOMETRY (all lengths in metres)
geom.boardX     = 50e-3;
geom.boardY     = 50e-3;
geom.boardThk   = 1.6e-3;

geom.patchX     = 27.503e-3;         % patch width
geom.patchY     = 32.100e-3;         % patch length (resonant, along feed)
geom.insetDepth = 6.900e-3;
geom.slotGap    = 0.750e-3;
geom.feedWidth  = 3.000e-3;

epsR        = 4.38;
lossTangent = 0.02;                  % generic FR-4; use datasheet value

fprintf("2.4 GHz PATCH - PROTOTYPE SIMULATION\n"); %[output:1913ec42]
fprintf("Band             : %.4f - %.4f GHz (centre %.4f GHz)\n", ... %[output:group:65fa15a9] %[output:62d5b90b]
    bandLow/1e9, bandHigh/1e9, fCenter/1e9); %[output:group:65fa15a9] %[output:62d5b90b]
fprintf("Substrate        : epsR %.2f, tan d %.3f, %.2f mm\n", ... %[output:group:4726ff81] %[output:6c8b0234]
    epsR, lossTangent, geom.boardThk*1e3); %[output:group:4726ff81] %[output:6c8b0234]
fprintf("Patch W x L      : %.3f x %.3f mm\n", geom.patchX*1e3, geom.patchY*1e3); %[output:48d79545]
fprintf("Inset / gap / feed: %.3f / %.3f / %.3f mm\n", ... %[output:group:3534fd2d] %[output:49c54e1e]
    geom.insetDepth*1e3, geom.slotGap*1e3, geom.feedWidth*1e3); %[output:group:3534fd2d] %[output:49c54e1e]
fprintf("Mesh max edge    : %.2f mm\n\n", maxEdge*1e3); %[output:72645a2f]

%% 3. BUILD ANTENNA
ant = buildInsetPatch(geom, epsR, lossTangent, maxEdge);

figure(Color="w"); %[output:8c269eba]
show(ant); %[output:8c269eba]
view(35,25); %[output:8c269eba]
title("2.4 GHz Inset-Fed Patch"); %[output:8c269eba]

%% 4. COARSE SWEEP - FIND TRUE RESONANCE
fprintf("Coarse sweep %.2f-%.2f GHz...\n", coarseSpan/1e9); %[output:622c549c]
fCoarse = coarseSpan(1):coarseStep:coarseSpan(2);
s11Coarse = s11FromAnt(ant, fCoarse, Z0);
[~, iC] = min(s11Coarse);
fDipCoarse = fCoarse(iC);

if iC == 1 || iC == numel(fCoarse)
    warning("S11 minimum is at the edge of the coarse sweep. " + ...
        "Resonance is outside %.1f-%.1f GHz; widen coarseSpan.", coarseSpan/1e9);
end

figure(Color="w"); %[output:9f3b2bfd]
plot(fCoarse/1e9, s11Coarse, LineWidth=1.8); hold on; grid on; %[output:9f3b2bfd]
xline([bandLow bandHigh]/1e9, "--"); %[output:9f3b2bfd]
yline(s11Limit, ":"); %[output:9f3b2bfd]
xlabel("Frequency (GHz)"); ylabel("S_{11} (dB)"); %[output:9f3b2bfd]
title("S_{11} - Wide Sweep"); %[output:9f3b2bfd]

%% 5. FINE SWEEP - BAND + RESONANCE
fStart = min(bandLow,  fDipCoarse) - fineMargin;
fStop  = max(bandHigh, fDipCoarse) + fineMargin;
freq = unique([fStart:fineStep:fStop, bandLow, fCenter, bandHigh]);

fprintf("Fine sweep %.3f-%.3f GHz (%d points)...\n", ... %[output:group:1d73c9ee] %[output:0dcce870]
    fStart/1e9, fStop/1e9, numel(freq)); %[output:group:1d73c9ee] %[output:0dcce870]
S = sparameters(ant, freq, Z0);
gamma = squeeze(S.Parameters(1,1,:)).';
S11dB = 20*log10(abs(gamma));
VSWR  = (1 + abs(gamma)) ./ (1 - abs(gamma));
Zin   = impedance(ant, freq);

%% 6. METRICS
[minS11, iDip] = min(S11dB);
fDip = freq(iDip);
dipAtEdge = (iDip == 1) || (iDip == numel(freq));

[fLo, fHi] = matchedBand(freq, S11dB, iDip, s11Limit);

inBand = freq >= bandLow & freq <= bandHigh;
worstS11InBand  = max(S11dB(inBand));
worstVSWRInBand = max(VSWR(inBand));

iLow  = find(freq == bandLow, 1);
iCtr  = find(freq == fCenter, 1);
iHigh = find(freq == bandHigh, 1);

% Resonant frequency scales roughly as 1/length
patchYSuggest = geom.patchY * fDip / fCenter;

%% 7. PRINT RESULTS
fprintf("\nRESULTS\n"); %[output:70bbef47]
fprintf("Resonance (S11 min) : %.4f GHz%s\n", fDip/1e9, ... %[output:group:5882a3c3] %[output:3b6f592b]
    ternary(dipAtEdge, "  (AT SWEEP EDGE - not a true dip)", "")); %[output:group:5882a3c3] %[output:3b6f592b]
fprintf("Offset from centre  : %+.1f MHz\n", (fDip - fCenter)/1e6); %[output:72434985]
fprintf("S11 at resonance    : %.2f dB\n", minS11); %[output:8719864b]
if isnan(fLo) %[output:group:473136bc]
    fprintf("-10 dB bandwidth    : none (never below %.0f dB)\n", s11Limit);
else
    fprintf("-10 dB bandwidth    : %.4f - %.4f GHz (%.1f MHz, %.2f%%)\n", ... %[output:591f9b75]
        fLo/1e9, fHi/1e9, (fHi-fLo)/1e6, 100*(fHi-fLo)/fDip); %[output:591f9b75]
end %[output:group:473136bc]
fprintf("\n%-10s %9s %8s %22s\n", "Freq", "S11 (dB)", "VSWR", "Zin (ohm)"); %[output:8cc62885]
for k = [iLow iCtr iHigh] %[output:group:6386fa96]
    fprintf("%.4f GHz %9.2f %8.2f %10.2f %+9.2fj\n", freq(k)/1e9, ... %[output:87020276]
        S11dB(k), VSWR(k), real(Zin(k)), imag(Zin(k))); %[output:87020276]
end %[output:group:6386fa96]
fprintf("\nWorst in-band S11   : %.2f dB\n", worstS11InBand); %[output:38f269ba]
fprintf("Worst in-band VSWR  : %.2f\n", worstVSWRInBand); %[output:81c42330]

if abs(fDip - fCenter) > 5e6 %[output:group:2117dadc]
    fprintf("\nSuggested next patch length (to centre resonance): %.3f mm\n", ... %[output:912a50cc]
        patchYSuggest*1e3); %[output:912a50cc]
    fprintf("  Re-tune inset depth for 50 ohm after changing length.\n"); %[output:84fce94d]
end %[output:group:2117dadc]

%% 8. PLOTS
% S11
figure(Color="w"); %[output:56bfa0da]
hS = plot(freq/1e9, S11dB, LineWidth=2); hold on; grid on; %[output:56bfa0da]
hB = xline(bandLow/1e9,  "--", "2.400",  LineWidth=1.2); %[output:56bfa0da]
     xline(bandHigh/1e9, "--", "2.4835", LineWidth=1.2); %[output:56bfa0da]
hL = yline(s11Limit, ":", "-10 dB", LineWidth=1.2); %[output:56bfa0da]
hD = plot(fDip/1e9, minS11, "o", MarkerSize=8, LineWidth=2); %[output:56bfa0da]
xlabel("Frequency (GHz)"); ylabel("S_{11} (dB)"); %[output:56bfa0da]
title("S_{11} - Fine Sweep"); %[output:56bfa0da]
legend([hS hB hL hD], ["S_{11}" "Band edges" "-10 dB" "Minimum"], Location="best"); %[output:56bfa0da]

% VSWR
figure(Color="w"); %[output:46f1fdb4]
plot(freq/1e9, VSWR, LineWidth=1.8); hold on; grid on; %[output:46f1fdb4]
xline([bandLow bandHigh]/1e9, "--"); %[output:46f1fdb4]
yline(2, ":", "VSWR = 2"); %[output:46f1fdb4]
ylim([1 10]); %[output:46f1fdb4]
xlabel("Frequency (GHz)"); ylabel("VSWR"); %[output:46f1fdb4]
title("VSWR"); %[output:46f1fdb4]

% Input impedance
figure(Color="w"); %[output:5037ba36]
hR = plot(freq/1e9, real(Zin), LineWidth=1.8); hold on; grid on; %[output:5037ba36]
hX = plot(freq/1e9, imag(Zin), LineWidth=1.8); %[output:5037ba36]
yline(Z0, "--", "50 \Omega"); %[output:5037ba36]
yline(0, ":"); %[output:5037ba36]
xline([bandLow bandHigh]/1e9, "--"); %[output:5037ba36]
xlabel("Frequency (GHz)"); ylabel("Impedance (\Omega)"); %[output:5037ba36]
title("Input Impedance"); %[output:5037ba36]
legend([hR hX], ["Resistance R" "Reactance X"], Location="best"); %[output:5037ba36]

% Smith chart
figure(Color="w"); %[output:17f8cab4]
smithplot(S); %[output:17f8cab4]
title("S_{11} Smith Chart"); %[output:17f8cab4]

%% 9. RADIATION PATTERN AT BAND CENTRE (computed once)
fprintf("\nCalculating gain pattern at %.4f GHz...\n", fCenter/1e9); %[output:7d2fb003]
az = -180:5:180;
el = -90:5:90;
G = pattern(ant, fCenter, az, el, Type="gain");   % numel(el) x numel(az), dBi
[AZ, EL] = meshgrid(az, el);

figure(Color="w"); %[output:400dc1ef]
patternCustom(G(:), 90 - EL(:), AZ(:)); %[output:400dc1ef]
title(sprintf("Gain Pattern at %.3f GHz (dBi)", fCenter/1e9)); %[output:400dc1ef]

maxGain      = max(G(:));
mismatchLoss = 10*log10(1 - abs(gamma(iCtr))^2);
realizedGain = maxGain + mismatchLoss;
gBroadside   = G(find(EL == 90, 1));
gBack        = G(find(EL == -90, 1));

fprintf("Max gain            : %.2f dBi\n", maxGain); %[output:856e67b2]
fprintf("Mismatch loss       : %.2f dB\n", mismatchLoss); %[output:18b56ce8]
fprintf("Max realized gain   : %.2f dBi\n", realizedGain); %[output:920288cb]
fprintf("Front-to-back ratio : %.1f dB\n", gBroadside - gBack); %[output:9e43328f]

%% 10. PASS / FAIL (whole band)
fprintf("\nDESIGN CHECK\n"); %[output:72fc3824]
resOK   = ~dipAtEdge && fDip >= bandLow && fDip <= bandHigh;
matchOK = worstS11InBand <= s11Limit;
vswrOK  = worstVSWRInBand <= 2;
fprintf("Resonance inside band      : %s\n", passFail(resOK)); %[output:7785a37e]
fprintf("S11 <= -10 dB across band  : %s\n", passFail(matchOK)); %[output:101a7d66]
fprintf("VSWR <= 2 across band      : %s\n", passFail(vswrOK)); %[output:3a212426]

%% 11. OPTIONAL: MESH CONVERGENCE STUDY
if runMeshStudy
    fprintf("\nMESH STUDY (resonance vs max edge length)\n");
    for k = 1:numel(meshStudyEdges)
        antK = buildInsetPatch(geom, epsR, lossTangent, meshStudyEdges(k));
        [fK, sK] = locateResonance(antK, fCoarse, coarseStep, fineStep, Z0);
        fprintf("  %.1f mm : %.4f GHz, %.2f dB\n", ...
            meshStudyEdges(k)*1e3, fK/1e9, sK);
    end
    fprintf("  Converged when resonance changes < ~0.5%% between steps.\n");
end

%% 12. OPTIONAL: SUBSTRATE TOLERANCE STUDY
if runToleranceStudy
    fprintf("\nTOLERANCE STUDY (epsR +/- %.2f)\n", epsRTolerance);
    for er = epsR + [-epsRTolerance 0 epsRTolerance]
        antK = buildInsetPatch(geom, er, lossTangent, maxEdge);
        [fK, sK] = locateResonance(antK, fCoarse, coarseStep, fineStep, Z0);
        fprintf("  epsR %.2f : %.4f GHz, %.2f dB\n", er, fK/1e9, sK);
    end
end

fprintf("\nSIMULATION COMPLETE.\n"); %[output:7f16ba2f]


%% ======================= LOCAL FUNCTIONS =======================

function ant = buildInsetPatch(g, epsR, lossTangent, maxEdge)
    substrate = dielectric(Name="Substrate", EpsilonR=epsR, ...
        LossTangent=lossTangent, Thickness=g.boardThk);

    board = antenna.Rectangle(Length=g.boardX, Width=g.boardY, Center=[0 0]);

    % Patch placement: centred in the space left after the feed margin
    feedMargin = 3e-3;
    availableFeedSpace = g.boardY - g.patchY - feedMargin;
    assert(availableFeedSpace > 0, "Patch too long for board.");
    assert(g.insetDepth < g.patchY, "Inset deeper than patch.");

    patchBottom  = -g.boardY/2 + feedMargin + availableFeedSpace/2;
    patchCenterY = patchBottom + g.patchY/2;
    patch = antenna.Rectangle(Length=g.patchX, Width=g.patchY, ...
        Center=[0 patchCenterY]);

    % Inset slots either side of the feed
    slotCenterX  = g.feedWidth/2 + g.slotGap/2;
    insetCenterY = patchBottom + g.insetDepth/2;
    leftSlot  = antenna.Rectangle(Length=g.slotGap, Width=g.insetDepth, ...
        Center=[-slotCenterX insetCenterY]);
    rightSlot = antenna.Rectangle(Length=g.slotGap, Width=g.insetDepth, ...
        Center=[ slotCenterX insetCenterY]);

    % Microstrip feed from board edge to inset point
    feedBottom = -g.boardY/2;
    feedTop    = patchBottom + g.insetDepth;
    feed = antenna.Rectangle(Length=g.feedWidth, Width=feedTop - feedBottom, ...
        Center=[0 (feedTop + feedBottom)/2]);

    topMetal = patch - leftSlot - rightSlot + feed;

    ant = pcbStack;
    ant.Name           = "2.4 GHz Inset-Fed Patch";
    ant.BoardShape     = board;
    ant.BoardThickness = g.boardThk;
    ant.Layers         = {topMetal, substrate, board};
    ant.FeedLocations  = [0, feedBottom + 1.5e-3, 1, 3];
    ant.FeedDiameter   = 0.6e-3;

    % Fixed mesh for repeatable results (suppress the mesh plot)
    fh = figure(Visible="off");
    mesh(ant, MaxEdgeLength=maxEdge);
    close(fh);
end

function s11 = s11FromAnt(ant, f, Z0)
    S = sparameters(ant, f, Z0);
    s11 = 20*log10(abs(squeeze(S.Parameters(1,1,:)))).';
end

function [fDip, s11Min] = locateResonance(ant, fCoarse, halfSpan, step, Z0)
    % Coarse sweep, then refine around the minimum
    s11C = s11FromAnt(ant, fCoarse, Z0);
    [~, i] = min(s11C);
    fR = max(fCoarse(1), fCoarse(i) - halfSpan) : step : ...
         min(fCoarse(end), fCoarse(i) + halfSpan);
    s11R = s11FromAnt(ant, fR, Z0);
    [s11Min, j] = min(s11R);
    fDip = fR(j);
end

function [fLo, fHi] = matchedBand(freq, s11dB, iDip, limit)
    % Contiguous region around the dip where S11 <= limit
    fLo = NaN; fHi = NaN;
    if s11dB(iDip) > limit, return; end
    lo = iDip;
    while lo > 1 && s11dB(lo-1) <= limit, lo = lo - 1; end
    hi = iDip;
    while hi < numel(freq) && s11dB(hi+1) <= limit, hi = hi + 1; end
    fLo = freq(lo);
    fHi = freq(hi);
end

function s = passFail(ok)
    s = ternary(ok, "PASS", "FAIL");
end

function out = ternary(cond, a, b)
    if cond, out = a; else, out = b; end
end

